struct Fasting { var start: Date?; var end: Date?; let goal: TimeInterval
    func finish(at now: Date) -> Fasting { var c = self; c.end = now; return c } }
enum Action { case start(Date), finish(Date) }
func reduce(_ s: Fasting, _ a: Action) -> Fasting {          // pure core
    switch a {
    case .start(let now):  return Fasting(start: now, end: s.end, goal: s.goal)
    case .finish(let now): return s.finish(at: now) }
}
@MainActor final class Store: ObservableObject {             // shell
    @Published private(set) var state: Fasting
    func send(_ a: Action) { state = reduce(state, a) } }

