typealias Reducer<S, A> = (S, A) -> S
typealias Middleware<S, A, D> = (S, A, D) async -> A?
@MainActor final class Store<S, A, D>: ObservableObject {     // shell
    @Published private(set) var state: S
    let reduce: Reducer<S, A>, deps: D, middlewares: [Middleware<S, A, D>]
    func send(_ a: A) async {
        state = reduce(state, a)                               // pure
        await withTaskGroup(of: A?.self) { group in             // effects
            for m in middlewares { group.addTask { await m(state, a, deps) } }
            for await next in group { if let next { await send(next) } } } }
}
